      "fdef_prot": "CREATE OR REPLACE FUNCTION public.protect_technician_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Allow updates during system reset_demo_data() execution
  IF current_setting('terrabyte.in_reset_demo', true) = 'true' THEN
    RETURN NEW;
  END IF;

  -- If is_verified is being modified, require caller to be an admin / service-centre
  IF NEW.is_verified IS DISTINCT FROM OLD.is_verified THEN
    IF public.current_user_role() != 'admin'::public.user_role THEN
      RAISE EXCEPTION 'Unauthorized: Technician verification status can only be modified by an administrator.'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
